/* Kilnworth. Signature: the glaze test tile. See DESIGN.md. */

:root {
  /* page: grey reduction-fired stoneware, not cream */
  --bg: oklch(0.95 0.006 230);
  --surface: oklch(0.985 0.003 230);
  --ink: oklch(0.24 0.02 50);
  --muted: oklch(0.44 0.015 240);
  --rule: oklch(0.62 0.012 240);
  --accent: oklch(0.45 0.16 262);
  --accent-deep: oklch(0.36 0.15 262);
  --on-accent: oklch(0.99 0 0);

  /* glazes: only ever inside a tile */
  --clay: oklch(0.8 0.028 60);
  --celadon: oklch(0.74 0.07 170);
  --tenmoku: oklch(0.3 0.05 45);
  --cobalt: oklch(0.46 0.15 262);
  --oatmeal: oklch(0.88 0.03 85);
  --copper: oklch(0.47 0.15 22);

  --display: "Bricolage Grotesque", "Arial Narrow", sans-serif;
  --body: "Source Serif 4", Georgia, serif;

  --s1: 0.5rem; --s2: 0.75rem; --s3: 1rem; --s4: 1.5rem; --s5: 2.5rem; --s6: 4rem; --s7: 6rem;
  --measure: 62ch;
  --page: min(72rem, 100% - 2 * var(--s4));
}

*, *::before, *::after { box-sizing: border-box; }

html { color-scheme: light; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 400 1.125rem/1.6 var(--body);
  -webkit-text-size-adjust: 100%;
}

::selection { background: var(--celadon); color: var(--ink); }

h1, h2, h3 {
  font-family: var(--display);
  font-stretch: 80%;
  font-weight: 750;
  line-height: 1.05;
  letter-spacing: -0.02em;
  text-wrap: balance;
  margin: 0;
}
h1 { font-size: clamp(2.75rem, 1.6rem + 5vw, 5.5rem); letter-spacing: -0.035em; line-height: 0.95; }
h2 { font-size: clamp(2rem, 1.4rem + 2.4vw, 3.2rem); }
h3 { font-size: 1.5rem; line-height: 1.15; }

p { margin: 0; text-wrap: pretty; }

a { color: var(--accent); text-underline-offset: 0.2em; text-decoration-thickness: 1px; }
@media (hover: hover) { a:hover { text-decoration-thickness: 2px; color: var(--accent-deep); } }

:focus-visible { outline: 3px solid var(--accent); outline-offset: 3px; border-radius: 2px; }

.skip {
  position: absolute; left: var(--s3); top: var(--s3); z-index: 10;
  padding: var(--s2) var(--s3); background: var(--ink); color: var(--surface);
  transform: translateY(-200%);
}
.skip:focus { transform: none; }

/* ---------- buttons ---------- */
.button {
  display: inline-flex; align-items: center; justify-content: center;
  min-height: 3rem; padding: 0.75rem 1.4rem;
  background: var(--accent); color: var(--on-accent);
  font: 700 1.0625rem/1.2 var(--display); font-stretch: 90%;
  text-decoration: none; border: 2px solid var(--accent); border-radius: 0.25rem 0.25rem 0.9rem 0.9rem;
  touch-action: manipulation;
  transition: background-color 160ms ease-out, border-color 160ms ease-out, color 160ms ease-out, transform 90ms ease-out;
}
@media (hover: hover) { .button:hover { background: var(--accent-deep); border-color: var(--accent-deep); color: var(--on-accent); } }
.button:active { background: var(--accent-deep); transform: translateY(1px); }
.button--small { min-height: 2.75rem; padding: 0.5rem 1rem; font-size: 1rem; }
.button--line { background: transparent; color: var(--accent); }
@media (hover: hover) { .button--line:hover { background: var(--accent); border-color: var(--accent); } }
.button--line:active { background: var(--accent); color: var(--on-accent); }

.link-quiet { color: var(--ink); font-weight: 600; }

/* ---------- the signature: a glaze test tile ----------
   Upright tile, hanging hole at the top, lower --dip of it glazed,
   glaze pooling a shade darker at the dip line. Always aria-hidden:
   the glaze or session count is always also in text. */
.tile {
  --glaze: var(--celadon);
  --dip: 65%;
  --w: 3.5rem;
  position: relative; display: block; flex: none;
  width: var(--w); aspect-ratio: 5 / 8;
  border-radius: calc(var(--w) * 0.08) calc(var(--w) * 0.08) calc(var(--w) * 0.14) calc(var(--w) * 0.14);
  background: linear-gradient(to top,
    var(--glaze) calc(var(--dip) - 4%),
    color-mix(in oklch, var(--glaze), black 22%) calc(var(--dip) - 4%) var(--dip),
    var(--clay) var(--dip));
  box-shadow: inset 0 0 0 1px oklch(0.3 0.02 60 / 0.25), 0 0.12em 0.3em oklch(0.3 0.02 240 / 0.18);
}
.tile::before { /* the hanging hole */
  content: ""; position: absolute; left: 50%; top: 9%;
  width: 22%; aspect-ratio: 1; translate: -50% 0; border-radius: 50%;
  background: var(--bg); box-shadow: inset 0 1px 2px oklch(0.3 0.02 60 / 0.45);
}
.tile--mini { --w: 0.95rem; --glaze: var(--accent); --dip: 60%; box-shadow: inset 0 0 0 1px oklch(0.3 0.02 60 / 0.3); }
.tile--mini::before { top: 12%; width: 26%; }
.tile--swatch { --w: 100%; max-width: 9rem; }

/* ---------- header ---------- */
.site-header {
  width: var(--page); margin-inline: auto;
  display: flex; flex-wrap: wrap; align-items: center; gap: var(--s2) var(--s4);
  padding-block: var(--s4);
}
.wordmark {
  font: 800 1.6rem/1 var(--display); font-stretch: 75%; letter-spacing: -0.02em;
  color: var(--ink); text-decoration: none; margin: 0;
}
.site-header nav { margin-inline-start: auto; }
.site-header nav ul { display: flex; gap: var(--s1); list-style: none; margin: 0; padding: 0; }
.site-header nav a {
  display: inline-flex; align-items: center; min-height: 2.75rem; padding-inline: var(--s2);
  color: var(--ink); font-weight: 600; text-decoration: none;
}
@media (hover: hover) { .site-header nav a:hover { text-decoration: underline; color: var(--ink); } }
@media (max-width: 34rem) {
  .site-header nav { order: 3; width: 100%; margin-inline-start: calc(var(--s2) * -1); }
  .site-header .button { margin-inline-start: auto; }
}

/* ---------- sections ---------- */
main > section { width: var(--page); margin-inline: auto; }

.hero {
  display: grid; gap: var(--s5); align-items: end;
  padding-block: var(--s5) var(--s7);
}
@media (min-width: 56rem) { .hero { grid-template-columns: 1.25fr 1fr; padding-block-start: var(--s6); } }
.hero__text { display: grid; gap: var(--s4); }
.lede { font-size: 1.25rem; max-width: 34ch; }
.hero__actions { display: flex; flex-wrap: wrap; align-items: center; gap: var(--s3) var(--s4); margin-top: var(--s1); }

.rack { margin: 0; }
.rack__tiles {
  display: flex; justify-content: space-between; align-items: end; gap: var(--s2);
  list-style: none; margin: 0; padding: var(--s4) var(--s3) var(--s3);
  border-bottom: 3px solid var(--ink); /* the shelf */
}
.rack__tiles li {
  display: grid; justify-items: center; gap: var(--s1);
  font: 600 0.875rem/1.2 var(--display); letter-spacing: 0.01em; color: var(--muted); text-align: center;
}
.rack__tiles .tile { --w: clamp(2.6rem, 11vw, 4.5rem); }
.rack__tiles li:nth-child(even) .tile { margin-bottom: var(--s3); }
.rack figcaption { margin-top: var(--s2); font-size: 0.9375rem; color: var(--muted); }

.section-head { display: grid; gap: var(--s3); max-width: var(--measure); margin-bottom: var(--s5); }
.section-head p { color: var(--muted); }

/* classes: ruled rows, not cards */
.classes { padding-block: var(--s6); }
.class-list { list-style: none; margin: 0; padding: 0; border-top: 2px solid var(--ink); }
.class {
  display: grid; gap: var(--s3) var(--s4);
  grid-template-columns: 1fr;
  padding-block: var(--s4) var(--s5);
  border-bottom: 1px solid var(--rule);
}
.class__body { display: grid; gap: var(--s2); max-width: 46ch; }
.sessions { display: flex; gap: 0.3rem; padding-top: 0.35rem; }
.class__facts { margin: 0; display: flex; flex-wrap: wrap; gap: var(--s2) var(--s5); }
.class__facts dt { font: 600 0.875rem/1.3 var(--display); color: var(--muted); letter-spacing: 0.01em; }
.class__facts dd { margin: 0; font: 700 1.25rem/1.3 var(--display); font-stretch: 90%; font-variant-numeric: tabular-nums; }
.class .button { justify-self: start; }
@media (min-width: 56rem) {
  .class { grid-template-columns: 5.5rem minmax(0, 1.3fr) minmax(0, 1fr) auto; align-items: start; }
  .class__facts { flex-direction: column; }
  .class .button { align-self: start; }
}
.booking-note { margin-top: var(--s4); max-width: var(--measure); font-size: 1rem; color: var(--muted); }

/* shop */
.shop { padding-block: var(--s6); }
.pieces {
  list-style: none; margin: 0; padding: 0;
  display: grid; gap: var(--s5) var(--s4);
  grid-template-columns: repeat(auto-fit, minmax(min(10rem, 100%), 1fr));
}
.piece { display: grid; gap: var(--s1); align-content: start; }
.piece .tile { margin-bottom: var(--s2); }
.piece h3 { font-size: 1.3rem; }
.piece__glaze { color: var(--muted); font-size: 1rem; }
.piece__price { font: 700 1.25rem/1.2 var(--display); font-variant-numeric: tabular-nums; }

/* story: one editorial column, offset right on wide screens */
.story {
  display: grid; gap: var(--s3);
  padding-block: var(--s6);
}
.story > * { max-width: var(--measure); }
.story p:first-of-type { font-size: 1.3rem; line-height: 1.5; }
@media (min-width: 56rem) { .story { padding-inline-start: 30%; } }

/* visit */
.visit { padding-block: var(--s6) var(--s7); }
.visit h2 { margin-bottom: var(--s5); }
.visit__grid { display: grid; gap: var(--s5); grid-template-columns: repeat(auto-fit, minmax(min(18rem, 100%), 1fr)); }
.visit h3 { font-size: 1.3rem; margin-bottom: var(--s3); }
.hours { margin: 0; }
.hours div { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 0 var(--s3); padding-block: var(--s2); border-bottom: 1px solid var(--rule); }
.hours dt { font-weight: 600; }
.hours dd { margin: 0; }
address { font-style: normal; margin-bottom: var(--s3); }

/* footer */
.site-footer {
  background: var(--ink); color: var(--surface);
  padding: var(--s5) max(var(--s4), (100% - 72rem) / 2);
  display: flex; flex-wrap: wrap; align-items: baseline; gap: var(--s3) var(--s5);
}
.site-footer .wordmark { color: var(--surface); }
.site-footer ul { display: flex; flex-wrap: wrap; gap: var(--s1) var(--s4); list-style: none; margin: 0; padding: 0; }
.site-footer a { color: var(--surface); display: inline-block; padding-block: 0.25rem; }
.site-footer :focus-visible { outline-color: var(--celadon); }
.site-footer__small { width: 100%; font-size: 0.9375rem; color: oklch(0.82 0.01 240); }

@media (prefers-reduced-motion: reduce) {
  .button { transition: background-color 120ms linear, border-color 120ms linear, color 120ms linear; }
  .button:active { transform: none; }
}

